from __future__ import annotations

from . import ImageFile


def create_stub_image_file(class_name, format_name, format_description, magic_bytes, accept_func, handler_func):
    """
    Create a StubImageFile subclass for a given image format.

    :param class_name: Name for the returned class.
    :param format_name: Image format identifier.
    :param format_description: Human readable format description.
    :param magic_bytes: Number of bytes to read from the file for acceptance checks.
    :param accept_func: Function accepting a byte prefix and returning True if the file is accepted.
    :param handler_func: Function returning the installed handler, or None.
    :return: A StubImageFile subclass.
    """

    class StubImageFile(ImageFile.StubImageFile):
        format = format_name
        format_description = format_description

        def _open(self):
            offset = self.fp.tell()

            if not accept_func(self.fp.read(magic_bytes)):
                msg = f"Not a {format_description} file"
                raise SyntaxError(msg)

            self.fp.seek(offset)

            # make something up
            self._mode = "F"
            self._size = 1, 1

            loader = self._load()
            if loader:
                loader.open(self)

        def _load(self):
            return handler_func()

    StubImageFile.__name__ = class_name
    return StubImageFile


def create_save_stub(format_description, handler_func):
    """
    Create a save function for a stub image adapter plugin.

    :param format_description: Human readable format description.
    :param handler_func: Function returning the installed handler, or None.
    :return: Save function matching PIL's plugin save signature.
    """

    def _save(im, fp, filename):
        handler = handler_func()
        if handler is None or not hasattr(handler, "save"):
            msg = f"{format_description} save handler not installed"
            raise OSError(msg)
        handler.save(im, fp, filename)

    return _save
